from __future__ import annotations
import csv, hashlib, json, sqlite3
from datetime import datetime, timezone
from pathlib import Path

def sha256_file(path: Path) -> str:
    h=hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda:f.read(1024*1024), b""):
            h.update(block)
    return h.hexdigest()

def list_schema(path: Path):
    con=sqlite3.connect(f"file:{path}?mode=ro", uri=True)
    try:
        return con.execute("SELECT name,type FROM sqlite_master WHERE type IN ('table','index') ORDER BY type,name").fetchall()
    finally:
        con.close()

def inventory(root: Path, out: Path):
    records=[]
    for p in sorted(root.rglob("*")):
        if p.is_symlink() or not p.is_file():
            continue
        st=p.stat()
        records.append({"path":str(p.relative_to(root)),"size":st.st_size,"sha256":sha256_file(p),"mtime_utc":datetime.fromtimestamp(st.st_mtime,timezone.utc).isoformat()})
    out.write_text(json.dumps({"files":records},indent=2),encoding="utf-8")

def timeline(csv_files, out):
    events=[]
    for fn,source in csv_files.items():
        with open(fn,newline='',encoding='utf-8') as f:
            for row in csv.DictReader(f):
                events.append({"source":source,"source_time":row["timestamp"],"event":row["event"],"subject":row.get("subject","")})
    events.sort(key=lambda e:e["source_time"])
    with open(out,'w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=["source","source_time","event","subject"])
        w.writeheader(); w.writerows(events)
